// Otopark bariyeri: araç yaklaşınca bariyer kalkar, gidince iner.
#include <Servo.h>  // Arduino IDE ile gelir

const int TRIG_PIN = 12;
const int ECHO_PIN = 11;
const int SERVO_PIN = 9;
const int KIRMIZI_PIN = 7;
const int YESIL_PIN = 4;
const int BUZZER_PIN = 2;

const int ARAC_ESIK_CM = 30;              // bundan yakın cisim "araç var" sayılır
const int KAPALI_ACI = 0;                 // bariyer yatay
const int ACIK_ACI = 90;                  // bariyer dik
const unsigned long GECIS_MS = 2000;      // araç gidince bariyer bu kadar bekler
const int ADIM_MS = 15;                   // her 2 derecede bekleme (yavaş hareket)

Servo bariyer;
int simdikiAci = KAPALI_ACI;
bool acik = false;
unsigned long sonArac = 0;

// Mesafeyi cm olarak döndürür; yankı gelmezse 0.
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long sure = pulseIn(ECHO_PIN, HIGH, 30000);  // en çok 30 ms bekle (~5 m)
  return sure / 58;
}

// Bariyeri hedef açıya yavaşça götürür.
void bariyerGotur(int hedef) {
  while (simdikiAci != hedef) {
    if (simdikiAci < hedef) simdikiAci = min(simdikiAci + 2, hedef);
    else simdikiAci = max(simdikiAci - 2, hedef);
    bariyer.write(simdikiAci);
    delay(ADIM_MS);
  }
}

void bariyerAc() {
  tone(BUZZER_PIN, 1500, 200);  // kısa bip
  digitalWrite(KIRMIZI_PIN, LOW);
  digitalWrite(YESIL_PIN, HIGH);
  bariyerGotur(ACIK_ACI);
  acik = true;
  Serial.println("Arac geldi: bariyer acik.");
}

void bariyerKapat() {
  bariyerGotur(KAPALI_ACI);
  digitalWrite(YESIL_PIN, LOW);
  digitalWrite(KIRMIZI_PIN, HIGH);
  acik = false;
  Serial.println("Arac gecti: bariyer kapali.");
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(KIRMIZI_PIN, OUTPUT);
  pinMode(YESIL_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  bariyer.attach(SERVO_PIN);
  bariyer.write(KAPALI_ACI);
  digitalWrite(KIRMIZI_PIN, HIGH);
  Serial.println("Hazir. Bariyer kapali.");
}

void loop() {
  long cm = mesafeOlc();
  bool aracVar = cm > 0 && cm < ARAC_ESIK_CM;

  if (aracVar) {
    sonArac = millis();
    if (!acik) bariyerAc();
  } else if (acik && millis() - sonArac > GECIS_MS) {
    bariyerKapat();
  }
  delay(100);
}
